function pushNotification(userId, title, text) {
    if (!userId) return;
    db.notifications = db.notifications || [];
    db.notifications.push({
        id: uid(),
        userId,
        title: String(title || ''),
        text: String(text || ''),
        createdAt: Date.now(),
        read: false
    });
    save();
}

