function deliveryQuote(restaurant, opts) {
    opts = opts || {};
    const latitude = Number(opts.lat);
    const longitude = Number(opts.lng);
    const useGps = Number.isFinite(latitude) && Number.isFinite(longitude) &&
        Math.abs(latitude) <= 90 && Math.abs(longitude) <= 180 &&
        (latitude !== 0 || longitude !== 0);

    const cfg = (db.settings && db.settings.delivery) || {
        baseFee: 12, perKm: 4, minFee: 15, maxFee: 70, driverSharePct: 0.8
    };

    let zoneId = '';
    let zoneName = '';
    let roadKm = 0;
    if (useGps) {
        const straight = Number.isFinite(restaurant.lat)
            ? haversineKm(restaurant, { lat: latitude, lng: longitude })
            : 0;
        roadKm = Math.max(0.5, straight * 1.25);
        zoneId = 'gps';
        zoneName = 'Mi ubicaciÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂÃÂ³n';
    } else {
        const zone = zoneById(opts.zoneId) || zoneById('z-centro');
        const straight = zone && Number.isFinite(restaurant.lat) && Number.isFinite(restaurant.lng)
            ? haversineKm(restaurant, zone)
            : 0;
        roadKm = Math.max(0.5, straight * 1.25);
        zoneId = zone ? zone.id : 'z-centro';
        zoneName = zone ? zone.name : 'Centro / Reforma';
    }
    const distanceKm = Math.round(roadKm * 10) / 10;
    const maxRadiusKm = Number(cfg.maxRadiusKm) || 25;
    const outOfRange = distanceKm > maxRadiusKm;
    const baseFee = Number(restaurant.deliveryFee) || Number(cfg.baseFee) || 12;
    const perKm = Number(cfg.perKm) || 4;
    const minFee = Number(cfg.minFee) || 15;
    const maxFee = Number(cfg.maxFee) || 70;
    const deliveryFee = money(Math.min(maxFee, Math.max(minFee, baseFee + perKm * distanceKm)));
    const driverSharePct = Math.min(1, Math.max(0, Number(cfg.driverSharePct) || 0.8));
    const driverEarnings = money(deliveryFee * driverSharePct);
    const deliveryPlatformFee = money(deliveryFee - driverEarnings);
    return {
        zoneId,
        zoneName,
        distanceKm,
        outOfRange,
        maxRadiusKm,
        baseFee: money(baseFee),
        perKm: money(perKm),
        minFee: money(minFee),
        maxFee: money(maxFee),
        deliveryFee,
        driverEarnings,
        deliveryPlatformFee
    };
}

